const D={up:[0,1],down:[0,-1],left:[-1,0],right:[1,0]};
const s=Math.SQRT1_2;
const Q={up:[-s,0,0,s],down:[s,0,0,s],left:[0,0,s,s],right:[0,0,-s,s]};
const won=st=>st.c===2&&st.r===2;
export function initialState(){return{c:0,r:0,moves:0,hint:null,msg:'Use the buttons or arrow keys to reach the goal.'};}
export function reduce({state,event}){
if(event.type!=='action')return state;
const a=event.action;
if(won(state))return{...state,msg:'Goal reached. Press Reset to play again.'};
if(a==='hint'){const h=state.c<2?'right':'up';return{...state,hint:h,msg:'Hint: move '+h+' to get one step closer.'};}
const d=D[a];if(!d)return state;
const c=state.c+d[0],r=state.r+d[1];
if(c<0||c>2||r<0||r>2)return{...state,hint:null,msg:'That move would leave the board.'};
const n={c,r,moves:state.moves+1,hint:null,msg:'Moved '+a+'.'};
if(won(n))n.msg='You reached the goal in '+n.moves+' moves (shortest route: 4).';
return n;}
export function evaluate({state}){
const st=state||initialState();
const x=(st.c-1)*1.1,z=(1-st.r)*1.1;
const w=won(st);
const nodes={token:{position:[x,0.35,z]},hintArrow:{visible:!!st.hint&&!w,position:[x,0.35,z]}};
if(st.hint)nodes.hintArrow.quaternion=Q[st.hint];
return{nodes,readouts:{moves:st.moves,dist:(2-st.c)+(2-st.r)},goal:{status:w?'won':'playing',message:st.msg}};}
